-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Agentes de Zenless Zone Zero: 60. Cada fila lleva todo: datos, icono, biografia y
-- materiales de ascension.
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.

insert into public.characters (
  id, game_id, name, image_url, rarity, element, level_cap, description, role, path, signature, is_upcoming, biography, biography_source, biography_en, biography_source_en, biography_es, biography_source_es, biography_es_translated, ascension
)
values
  ('zzz-alice', 'zenless-zone-zero', 'Alice', 'https://enka.network/ui/zzz/IconRoleCircle46.png', 'S', 'Físico', null, null, 'Anomalía', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
  ('zzz-anby', 'zenless-zone-zero', 'Anby Demara', 'https://enka.network/ui/zzz/IconRoleCircle01.png', 'A', 'Eléctrico', 60, null, 'Sub-DPS / Debuffer', 'Aturdimiento', 'Batería Demara II', false, 'A mysterious young girl who never talks about her past, almost as if she didn''t have one. She is calm and collected, and unusually competent and efficient in combat, almost as if she''d had years of training. In an unexpected incident, Nicole brought her back to the Cunning Hares, and she''s has an emotional independence on her ever since. She loves watching movies, but due to certain lack of common sense she seems to almost think them real-life stories.

Anby Demara is a highly skilled member of the Cunning Hares and a former soldier of the New Eridu Defense Force. Though she lacks basic social skills, Anby makes up for it with her advanced combat prowess and Hollow knowledge gained from her genetic cloning and time as Soldier 0.

Anby has two notable special interests: movies and hamburgers, the former she uses as reference for real life events, and the latter her favorite food due to its taste, affordability, and complete nutritional value.', 'https://zenless-zone-zero.fandom.com/wiki/Anby%2FLore', 'A mysterious young girl who never talks about her past, almost as if she didn''t have one. She is calm and collected, and unusually competent and efficient in combat, almost as if she''d had years of training. In an unexpected incident, Nicole brought her back to the Cunning Hares, and she''s has an emotional independence on her ever since. She loves watching movies, but due to certain lack of common sense she seems to almost think them real-life stories.

Anby Demara is a highly skilled member of the Cunning Hares and a former soldier of the New Eridu Defense Force. Though she lacks basic social skills, Anby makes up for it with her advanced combat prowess and Hollow knowledge gained from her genetic cloning and time as Soldier 0.

Anby has two notable special interests: movies and hamburgers, the former she uses as reference for real life events, and the latter her favorite food due to its taste, affordability, and complete nutritional value.', 'https://zenless-zone-zero.fandom.com/wiki/Anby%2FLore', 'Una joven misteriosa que nunca habla de su pasado, casi como si no tuviera ninguno. Es serena y templada, y en combate resulta inusualmente competente y eficaz, como si llevara años entrenando. Tras un incidente inesperado, Nicole la llevó con las Liebres Astutas, y desde entonces depende emocionalmente de ella. Le encanta ver películas, pero por cierta falta de sentido común parece tomárselas casi como historias reales.

Anby Demara es una integrante muy capaz de las Liebres Astutas y antigua soldado de la Fuerza de Defensa de Nueva Eridu. Aunque carece de habilidades sociales básicas, lo compensa con su destreza en combate y su conocimiento de los Hollows, adquiridos durante su clonación genética y su etapa como Soldado 0.

Anby tiene dos aficiones muy marcadas: el cine y las hamburguesas. Las primeras le sirven de referencia para interpretar la vida real; las segundas son su comida favorita por su sabor, su precio y su valor nutricional.', 'https://zenless-zone-zero.fandom.com/wiki/Anby%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-anton', 'zenless-zone-zero', 'Anton Ivanov', 'https://enka.network/ui/zzz/IconRoleCircle15.png', 'A', 'Eléctrico', 60, null, 'DPS', 'Ataque', 'Taladro del eje rojo', false, 'Leads Others in His Passion for Work A senior staff member of Belobog Industries, he''s an onsite project manager who''s always ready to go. Energetic and Reliable He''s full of vigor and always rises to the occasion. Kind-Hearted Despite Appearances With a sharp tongue but a soft heart, he can''t say "no" to those in need. Strong, Sincere & Straightforward Open and honest, nothing can seem to upset him.', 'https://zenless-zone-zero.fandom.com/wiki/Anton%2FLore', 'Leads Others in His Passion for Work A senior staff member of Belobog Industries, he''s an onsite project manager who''s always ready to go. Energetic and Reliable He''s full of vigor and always rises to the occasion. Kind-Hearted Despite Appearances With a sharp tongue but a soft heart, he can''t say "no" to those in need. Strong, Sincere & Straightforward Open and honest, nothing can seem to upset him.', 'https://zenless-zone-zero.fandom.com/wiki/Anton%2FLore', 'Contagia a los demás su pasión por el trabajo: veterano de Industrias Belobog, es un jefe de obra siempre dispuesto a arrancar. Enérgico y de fiar, rebosa vigor y siempre está a la altura de las circunstancias. De apariencia dura pero buen corazón: tiene la lengua afilada y el alma blanda, y es incapaz de decir "no" a quien lo necesita. Fuerte, sincero y directo: es tan abierto y honesto que nada parece capaz de amargarle el día.', 'https://zenless-zone-zero.fandom.com/wiki/Anton%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
