  ('zzz-banyue', 'zenless-zone-zero', 'Banyue', 'https://enka.network/ui/zzz/IconRoleCircle53.png', 'S', 'Fuego', null, null, 'Ruptura', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin01.webp","nombre":"Insignia disruptiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin02.webp","nombre":"Insignia disruptiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin02.webp","nombre":"Insignia disruptiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin03.webp","nombre":"Insignia dictaminadora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin03.webp","nombre":"Insignia dictaminadora","cantidad":20}]}]'::jsonb),
  ('zzz-ben', 'zenless-zone-zero', 'Ben Bigger', 'https://enka.network/ui/zzz/IconRoleCircle16.png', 'A', 'Fuego', 60, null, 'Tanque / Sub-DPS', 'Defensa', 'Cilindro enorme', false, 'Strong Body & Honest Soul Those paws could shatter bones, luckily they''re busy tapping away on a calculator. Has His Fish and Eats It Too Finds an easy ballance between fighting thugs with his pillar on the battlefield and returning to accounting at the times of peace... The only thing that could make it all better is a jar of caviar. Fuzzy Fur, No Fuzzy Math Naturally sensitive to all things numerical, he''s careful in his bookkeeping, and has memorized all 58 account ledgers in his office. Repays Recognition With Loyalty After 1 year and 321 days of employment, Koleda promoted him to Head of Finance, and he''s followed her faithfully ever since.', 'https://zenless-zone-zero.fandom.com/wiki/Ben%2FLore', 'Strong Body & Honest Soul Those paws could shatter bones, luckily they''re busy tapping away on a calculator. Has His Fish and Eats It Too Finds an easy ballance between fighting thugs with his pillar on the battlefield and returning to accounting at the times of peace... The only thing that could make it all better is a jar of caviar. Fuzzy Fur, No Fuzzy Math Naturally sensitive to all things numerical, he''s careful in his bookkeeping, and has memorized all 58 account ledgers in his office. Repays Recognition With Loyalty After 1 year and 321 days of employment, Koleda promoted him to Head of Finance, and he''s followed her faithfully ever since.', 'https://zenless-zone-zero.fandom.com/wiki/Ben%2FLore', 'Cuerpo fuerte y alma honesta: esas zarpas podrían romper huesos, pero por suerte están ocupadas tecleando en una calculadora. Sabe compaginarlo todo: alterna sin problema entre repartir mamporros con su pilar en el campo de batalla y volver a la contabilidad en tiempos de paz... Lo único que podría mejorarlo es un tarro de caviar. Mucho pelo, pero ninguna cuenta peluda: es sensible por naturaleza a todo lo numérico, cuidadoso con sus libros y se ha memorizado los 58 libros de cuentas de su oficina. Devuelve el reconocimiento con lealtad: tras 1 año y 321 días de trabajo, Koleda lo ascendió a jefe de finanzas, y desde entonces la sigue con absoluta fidelidad.', 'https://zenless-zone-zero.fandom.com/wiki/Ben%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield01.webp","nombre":"Insignia defensiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":20}]}]'::jsonb),
  ('zzz-starlight-billy', 'zenless-zone-zero', 'Billy Estelar (Starlight - Billy)', 'https://enka.network/ui/zzz/IconRoleCircle62.png', 'S', 'Físico', null, null, 'Ruptura', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin01.webp","nombre":"Insignia disruptiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin02.webp","nombre":"Insignia disruptiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin02.webp","nombre":"Insignia disruptiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin03.webp","nombre":"Insignia dictaminadora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin03.webp","nombre":"Insignia dictaminadora","cantidad":20}]}]'::jsonb),
  ('zzz-billy', 'zenless-zone-zero', 'Billy Kid', 'https://enka.network/ui/zzz/IconRoleCircle10.png', 'A', 'Físico', 60, null, 'DPS', 'Ataque', 'Réplica del motor estelar', false, 'A handsome android with a casual and carefree personality. He''s an avid fan of the Starlight Knight show, not only referring to himself as one of the Starlight Knights, but repeating many classic lines from the show. Refers to his pair of special custom-made high-caliber revolvers as "the girls". They appear to have been a gift from an old friend. He may look unreliable, but once he gets serious Billy can take on any challenge.

"The White Chariot" of the Cunning Hares and Former "Red Scarf" of Calydon, Billy Kid is an Intelligent Construct made for combat. Despite having a childish personality and fascination for the TV show Starlight Knight and the idol Monica, Billy is a skilled and powerful fighter, having once been an Outer Ring Champion and being able to outmatch Lighter in a fistfight.

Armed with a pair of revolvers, Billy fights countless threats inside Hollows as part of his job, though he does have a tendency to forget his ammo count.', 'https://zenless-zone-zero.fandom.com/wiki/Billy%2FLore', 'A handsome android with a casual and carefree personality. He''s an avid fan of the Starlight Knight show, not only referring to himself as one of the Starlight Knights, but repeating many classic lines from the show. Refers to his pair of special custom-made high-caliber revolvers as "the girls". They appear to have been a gift from an old friend. He may look unreliable, but once he gets serious Billy can take on any challenge.

"The White Chariot" of the Cunning Hares and Former "Red Scarf" of Calydon, Billy Kid is an Intelligent Construct made for combat. Despite having a childish personality and fascination for the TV show Starlight Knight and the idol Monica, Billy is a skilled and powerful fighter, having once been an Outer Ring Champion and being able to outmatch Lighter in a fistfight.

Armed with a pair of revolvers, Billy fights countless threats inside Hollows as part of his job, though he does have a tendency to forget his ammo count.', 'https://zenless-zone-zero.fandom.com/wiki/Billy%2FLore', 'Un androide atractivo de carácter despreocupado y campechano. Es fan acérrimo de la serie El Caballero Estelar: no solo se considera uno de sus caballeros, sino que repite muchas de sus frases más célebres. A su pareja de revólveres de alto calibre hechos a medida los llama "las chicas", y parecen haber sido el regalo de un viejo amigo. Puede parecer poco de fiar, pero cuando se pone serio, Billy es capaz de afrontar cualquier reto.

"El Carro Blanco" de las Liebres Astutas y antiguo "Pañuelo Rojo" de Calydon, Billy Kid es un constructo inteligente creado para el combate. Pese a su personalidad infantil y su fascinación por El Caballero Estelar y la ídolo Monica, Billy es un luchador hábil y poderoso: llegó a ser campeón del Anillo Exterior y puede superar a Lighter en un combate cuerpo a cuerpo.', 'https://zenless-zone-zero.fandom.com/wiki/Billy%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-burnice', 'zenless-zone-zero', 'Burnice White', 'https://enka.network/ui/zzz/IconRoleCircle32.png', 'S', 'Fuego', 60, null, 'Sub-DPS / Debuffer (DoT)', 'Anomalía', 'Agitador de llamas', false, 'Mixologist, fuel chemist, and pyromaniac, Burnice White can be considered the jack-of-all-trades of the Sons of Calydon. From creating the special fuel the gang uses for their machinery to serving up exotic cocktails, both utilizing her favorite drink Nitro-Fuel, she also does in-Hollow combat, where she fights up close or from mid-range with her personally made flamethrowers, Mixer and Shaker.

Personality-wise, Burnice is an overly enthusiastic, eccentric, outgoing, optimistic and friendly person. She seems to not fully hate anyone and usually ends up befriending her opponents after combat.

Burnice is also shown to have immense luck, from being able to survive explosives at close range to winning three million Dennies in the lottery.', 'https://zenless-zone-zero.fandom.com/wiki/Burnice%2FLore', 'Mixologist, fuel chemist, and pyromaniac, Burnice White can be considered the jack-of-all-trades of the Sons of Calydon. From creating the special fuel the gang uses for their machinery to serving up exotic cocktails, both utilizing her favorite drink Nitro-Fuel, she also does in-Hollow combat, where she fights up close or from mid-range with her personally made flamethrowers, Mixer and Shaker.

Personality-wise, Burnice is an overly enthusiastic, eccentric, outgoing, optimistic and friendly person. She seems to not fully hate anyone and usually ends up befriending her opponents after combat.

Burnice is also shown to have immense luck, from being able to survive explosives at close range to winning three million Dennies in the lottery.', 'https://zenless-zone-zero.fandom.com/wiki/Burnice%2FLore', 'Coctelera, química de combustibles y pirómana, Burnice White puede considerarse la mujer orquesta de los Hijos de Calydon. Lo mismo fabrica el combustible especial que la banda usa en su maquinaria que sirve cócteles exóticos, en ambos casos con su bebida favorita, el Nitrocombustible. Además combate dentro de los Hollows, donde pelea de cerca o a media distancia con sus lanzallamas caseros, Mixer y Shaker.

En lo personal, Burnice es entusiasta hasta el exceso, excéntrica, extrovertida, optimista y cercana. No parece odiar a nadie del todo y suele acabar haciéndose amiga de sus rivales tras el combate.

También goza de una suerte inmensa: ha sobrevivido a explosiones a bocajarro y ha ganado tres millones de dennies en la lotería.', 'https://zenless-zone-zero.fandom.com/wiki/Burnice%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
  ('zzz-caesar', 'zenless-zone-zero', 'Caesar King', 'https://enka.network/ui/zzz/IconRoleCircle25.png', 'S', 'Físico', 60, null, 'Tanque / Buffer', 'Defensa', 'Colmillos de furia', false, 'Yes! It''s the formidable leader of the Sons of Calydon, Caesar! She must have faced many difficulties as the leader of the Sons of Calydon to bring the gang to where it is today, right? "Huh? Not at all! The Sons of Calydon of today is a testament to everyone''s hard work!"

"I''m Caesar herself, the leader of Sons of Calydon." Caesar King "Take a seat anywhere you like. Make yourself at home." "As you''ve come all the way to the Outer Ring, consider yourself a guest of the Sons of Calydon!" "Uhh... Big Daddy, what does she mean by ''the exchange of gifts''?"', 'https://zenless-zone-zero.fandom.com/wiki/Caesar%2FLore', 'Yes! It''s the formidable leader of the Sons of Calydon, Caesar! She must have faced many difficulties as the leader of the Sons of Calydon to bring the gang to where it is today, right? "Huh? Not at all! The Sons of Calydon of today is a testament to everyone''s hard work!"

"I''m Caesar herself, the leader of Sons of Calydon." Caesar King "Take a seat anywhere you like. Make yourself at home." "As you''ve come all the way to the Outer Ring, consider yourself a guest of the Sons of Calydon!" "Uhh... Big Daddy, what does she mean by ''the exchange of gifts''?"', 'https://zenless-zone-zero.fandom.com/wiki/Caesar%2FLore', '¡Sí! Es la formidable líder de los Hijos de Calydon, ¡Caesar! Habrá tenido que superar muchas dificultades al frente de la banda para llevarla hasta donde está hoy, ¿verdad? "¿Eh? ¡Para nada! ¡Los Hijos de Calydon de hoy son el resultado del esfuerzo de todos!".

"Soy Caesar en persona, la líder de los Hijos de Calydon". Caesar King. "Siéntate donde quieras. Estás en tu casa". "Ya que has venido hasta el Anillo Exterior, ¡considérate invitada de los Hijos de Calydon!". "Eh... Papá Grande, ¿a qué se refiere con lo del intercambio de regalos?".', 'https://zenless-zone-zero.fandom.com/wiki/Caesar%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield01.webp","nombre":"Insignia defensiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":20}]}]'::jsonb),
