  ('zzz-claret', 'zenless-zone-zero', 'Claret', 'https://enka.network/ui/zzz/IconRoleCircle1611.png', 'S', 'Eléctrico', null, null, 'Blindaje', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankArmorer01.webp","nombre":"Insignia de armero básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankArmorer02.webp","nombre":"Insignia de armero avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankArmorer02.webp","nombre":"Insignia de armero avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankArmorer03.webp","nombre":"Insignia metalúrgica","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankArmorer03.webp","nombre":"Insignia metalúrgica","cantidad":20}]}]'::jsonb),
  ('zzz-corin', 'zenless-zone-zero', 'Corin Wickes', 'https://enka.network/ui/zzz/IconRoleCircle09.png', 'A', 'Físico', 60, null, 'DPS', 'Ataque', 'Ama de llaves', false, 'Corin Wickes is a young maid working for Victoria Housekeeping Co. who has notable self esteem and confidence issues. Once a sickly girl who required major surgery, Corin is now an exceptional combatant who takes an intimidating and devastating ''chainsaw'' with her wherever she goes, be it for in-Hollow commissions, for maid-related tasks, and for everyday life. Though timid, lacking self-esteem and constantly apologizing for anything and everything, Corin is one of Victoria Housekeeping''s most reliable members, sporting a flawless performance and never failing to fulfill her tasks. On rare occasions, Corin shows notable initiative and confidence; at times like this, she rarely stutters or apologizes.', 'https://zenless-zone-zero.fandom.com/wiki/Corin%2FLore', 'Corin Wickes is a young maid working for Victoria Housekeeping Co. who has notable self esteem and confidence issues. Once a sickly girl who required major surgery, Corin is now an exceptional combatant who takes an intimidating and devastating ''chainsaw'' with her wherever she goes, be it for in-Hollow commissions, for maid-related tasks, and for everyday life. Though timid, lacking self-esteem and constantly apologizing for anything and everything, Corin is one of Victoria Housekeeping''s most reliable members, sporting a flawless performance and never failing to fulfill her tasks. On rare occasions, Corin shows notable initiative and confidence; at times like this, she rarely stutters or apologizes.', 'https://zenless-zone-zero.fandom.com/wiki/Corin%2FLore', 'Corin Wickes es una joven doncella de Victoria Housekeeping con serios problemas de autoestima y confianza. Antes era una niña enfermiza que necesitó una operación importante; hoy es una combatiente excepcional que lleva consigo una intimidante y devastadora "motosierra" a todas partes, ya sea para encargos dentro de un Hollow, para sus tareas domésticas o para el día a día. Aunque es tímida, insegura y se disculpa constantemente por todo, Corin es una de las integrantes más fiables de Victoria Housekeeping: su desempeño es impecable y nunca deja una tarea sin cumplir. En contadas ocasiones muestra una iniciativa y una seguridad notables; en esos momentos, rara vez tartamudea o pide perdón.', 'https://zenless-zone-zero.fandom.com/wiki/Corin%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-dialyn', 'zenless-zone-zero', 'Dialyn', 'https://enka.network/ui/zzz/IconRoleCircle54.png', 'S', 'Físico', null, null, 'Aturdimiento', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-ellen', 'zenless-zone-zero', 'Ellen Joe', 'https://enka.network/ui/zzz/IconRoleCircle21.png', 'S', 'Hielo', 60, null, 'DPS', 'Ataque', 'Visitante de las profundidades', false, 'Ellen Joe is a laid-back Shark Thiren that attends school in New Eridu who hates activities that require energy. Despite her personality and aloofness, Ellen is a significantly popular student at the school, though she prefers spending time with fellow students Ruby, Monna, and Lynn at karaoke bars, Godfinger and more.

Ellen''s school life is balanced with her job as a maid for Victoria Housekeeping Co., where she specializes in security management and garden maintenance. Though she dislikes physical activities, the support of her teammates that she considers her friend as well, allow her to unleash formidable power, becoming a significant threat in combat.', 'https://zenless-zone-zero.fandom.com/wiki/Ellen%2FLore', 'Ellen Joe is a laid-back Shark Thiren that attends school in New Eridu who hates activities that require energy. Despite her personality and aloofness, Ellen is a significantly popular student at the school, though she prefers spending time with fellow students Ruby, Monna, and Lynn at karaoke bars, Godfinger and more.

Ellen''s school life is balanced with her job as a maid for Victoria Housekeeping Co., where she specializes in security management and garden maintenance. Though she dislikes physical activities, the support of her teammates that she considers her friend as well, allow her to unleash formidable power, becoming a significant threat in combat.', 'https://zenless-zone-zero.fandom.com/wiki/Ellen%2FLore', 'Ellen Joe es una tiren tiburón de carácter tranquilo que estudia en Nueva Eridu y detesta cualquier actividad que exija energía. Pese a su personalidad distante, es una alumna bastante popular en el instituto, aunque prefiere pasar el rato con sus compañeras Ruby, Monna y Lynn en karaokes, en el Godfinger y sitios por el estilo.

Compagina la vida escolar con su trabajo de doncella en Victoria Housekeeping, donde se especializa en seguridad y en el mantenimiento del jardín. Aunque le desagrada el esfuerzo físico, el apoyo de sus compañeras, a las que también considera amigas, le permite desatar un poder formidable y convertirse en una amenaza seria en combate.', 'https://zenless-zone-zero.fandom.com/wiki/Ellen%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-evelyn', 'zenless-zone-zero', 'Evelyn', 'https://enka.network/ui/zzz/IconRoleCircle37.png', 'S', 'Fuego', null, null, 'Ataque', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-trigger', 'zenless-zone-zero', 'Gatillo (Trigger)', 'https://enka.network/ui/zzz/IconRoleCircle39.png', 'S', 'Eléctrico', null, null, 'Aturdimiento', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-grace', 'zenless-zone-zero', 'Grace Howard', 'https://enka.network/ui/zzz/IconRoleCircle20.png', 'S', 'Eléctrico', 60, null, 'DPS (DoT) / Debuffer', 'Anomalía', 'Cámara de fusión', false, 'Grace Howard is the eccentric, machine-obsessed R&D specialist of Belobog Heavy Industries, and adoptive sister to Belobog''s current president, Koleda. She is responsible for the new-generation of in-Hollow Smart Machinery the company uses. Whilst having a notable interest in dismantling and examining machinery, Grace also sees creations of her own as her ''children,'' ready to protect them at any given moment. Outside of mechanics and engineering, Grace Howard is known for her acrobatic prowess in combat, capable of dodging various forms of gunfire and etheric attacks, whilst fighting back with a weaponized nail gun and electric grenades.', 'https://zenless-zone-zero.fandom.com/wiki/Grace%2FLore', 'Grace Howard is the eccentric, machine-obsessed R&D specialist of Belobog Heavy Industries, and adoptive sister to Belobog''s current president, Koleda. She is responsible for the new-generation of in-Hollow Smart Machinery the company uses. Whilst having a notable interest in dismantling and examining machinery, Grace also sees creations of her own as her ''children,'' ready to protect them at any given moment. Outside of mechanics and engineering, Grace Howard is known for her acrobatic prowess in combat, capable of dodging various forms of gunfire and etheric attacks, whilst fighting back with a weaponized nail gun and electric grenades.', 'https://zenless-zone-zero.fandom.com/wiki/Grace%2FLore', 'Grace Howard es la excéntrica especialista en I+D de Industrias Pesadas Belobog, obsesionada con las máquinas, y hermana adoptiva de Koleda, la actual presidenta. Es la responsable de la nueva generación de maquinaria inteligente que la empresa usa dentro de los Hollows. Además de su interés por desmontar y examinar aparatos, Grace considera a sus creaciones sus "hijas" y está dispuesta a protegerlas en cualquier momento. Fuera de la mecánica y la ingeniería, destaca por su agilidad acrobática en combate: es capaz de esquivar todo tipo de disparos y ataques etéricos mientras responde con una pistola de clavos modificada y granadas eléctricas.', 'https://zenless-zone-zero.fandom.com/wiki/Grace%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
  ('zzz-harumasa', 'zenless-zone-zero', 'Harumasa', 'https://enka.network/ui/zzz/IconRoleCircle35.png', 'S', 'Eléctrico', 60, null, 'DPS', 'Ataque', 'Motor-W de firma de Harumasa', false, 'Asaba Harumasa is the carefree expert archer of Hollow Special Operations Section 6. A child prodigy with both bow and blade, Harumasa aids his teammates from afar, while also being able to switch to close combat if necessary. He has little interest in work, and tries his best to slack off, usually doing things to the acceptable minimum and napping for the rest of the job as he waits to clock out.

Harumasa''s life has been deeply impacted by Ether Aptitude Regression Syndrome, a health condition he was born with. The boon of an exceptional Ether aptitude is outweighed by the toll it takes on his body, which he uses as a reason to apply for sick leave. Due to the medicine he takes, Harumasa gained a liking for bitter flavors.', 'https://zenless-zone-zero.fandom.com/wiki/Harumasa%2FLore', 'Asaba Harumasa is the carefree expert archer of Hollow Special Operations Section 6. A child prodigy with both bow and blade, Harumasa aids his teammates from afar, while also being able to switch to close combat if necessary. He has little interest in work, and tries his best to slack off, usually doing things to the acceptable minimum and napping for the rest of the job as he waits to clock out.

Harumasa''s life has been deeply impacted by Ether Aptitude Regression Syndrome, a health condition he was born with. The boon of an exceptional Ether aptitude is outweighed by the toll it takes on his body, which he uses as a reason to apply for sick leave. Due to the medicine he takes, Harumasa gained a liking for bitter flavors.', 'https://zenless-zone-zero.fandom.com/wiki/Harumasa%2FLore', 'Asaba Harumasa es el despreocupado arquero experto de la Sección 6 de Operaciones Especiales de Hollows. Niño prodigio tanto con el arco como con la espada, apoya a sus compañeros desde la distancia y puede pasar al cuerpo a cuerpo si hace falta. El trabajo le interesa poco y hace lo posible por escaquearse: cumple el mínimo aceptable y dedica el resto de la jornada a echar una cabezada mientras espera a fichar la salida.

Su vida está muy marcada por el síndrome de regresión de aptitud etérica, una dolencia congénita. La ventaja de una aptitud etérica excepcional queda contrarrestada por el precio que le cobra al cuerpo, algo que él aprovecha para pedir la baja. Por la medicación que toma, Harumasa ha acabado tomándole gusto a los sabores amargos.', 'https://zenless-zone-zero.fandom.com/wiki/Harumasa%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-hugo', 'zenless-zone-zero', 'Hugo', 'https://enka.network/ui/zzz/IconRoleCircle42.png', 'S', 'Hielo', null, null, 'Ataque', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-jane-doe', 'zenless-zone-zero', 'Jane Doe', 'https://enka.network/ui/zzz/IconRoleCircle24.png', 'S', 'Físico', 60, null, 'DPS (DoT)', 'Anomalía', 'Púas afiladas', false, 'This time we''re going to introduce Emma... Err, wait... I mean Kylie! No, that''s not quite right... Apparently, there''s another archive that is a little different. Is it perhaps... Jane? Last I heard it was Anne! Jane: "I didn''t expect you to know me so well. I''m delighted! Well, truth be told, it''s all true!"

"Well, last time was last time! This time, I''m telling the truth. Trust me~" Jane Doe What am I? A cat Thiren. You bet I''m the real deal. "*sigh*... Having such a rare lineage used to give me quite a headache." 
"Why would I lie to you? Meow~', 'https://zenless-zone-zero.fandom.com/wiki/Jane%20Doe%2FLore', 'This time we''re going to introduce Emma... Err, wait... I mean Kylie! No, that''s not quite right... Apparently, there''s another archive that is a little different. Is it perhaps... Jane? Last I heard it was Anne! Jane: "I didn''t expect you to know me so well. I''m delighted! Well, truth be told, it''s all true!"

"Well, last time was last time! This time, I''m telling the truth. Trust me~" Jane Doe What am I? A cat Thiren. You bet I''m the real deal. "*sigh*... Having such a rare lineage used to give me quite a headache." 
"Why would I lie to you? Meow~', 'https://zenless-zone-zero.fandom.com/wiki/Jane%20Doe%2FLore', 'Esta vez vamos a presentar a Emma... Eh, espera... ¡Quiero decir Kylie! No, tampoco es eso... Por lo visto hay otro archivo algo distinto. ¿Será quizá... Jane? ¡La última vez me dijeron que era Anne! Jane: "No esperaba que me conocieras tan bien. ¡Qué ilusión! Bueno, la verdad es que todo eso es cierto".

"¡Lo de la última vez fue la última vez! Esta vez digo la verdad, créeme~". Jane Doe. ¿Que qué soy? Una tiren gata. Puedes apostar a que soy auténtica. "*suspiro*... Tener un linaje tan raro solía darme más de un dolor de cabeza". "¿Por qué iba a mentirte? Miau~".', 'https://zenless-zone-zero.fandom.com/wiki/Jane%20Doe%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
  ('zzz-ju-fufu', 'zenless-zone-zero', 'Ju Fufu', 'https://enka.network/ui/zzz/IconRoleCircle43.png', 'S', 'Fuego', null, null, 'Aturdimiento', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-koleda', 'zenless-zone-zero', 'Koleda Belobog', 'https://enka.network/ui/zzz/IconRoleCircle14.png', 'S', 'Fuego', 60, null, 'Sub-DPS / Debuffer', 'Aturdimiento', 'Horno infernal', false, 'Small & Cute, With Some Fierce Combat Power She may be small, but can certainly wield that huge hammer. A Fierce Young Girl Who''s Also a President The young leader at the helm of Belobog Industries. A President Who Leads by Example She prefers to work out in the field, rather than being stuck at a desk. Leads by Example While Maintaining Her Cute Nature Her maturity sometimes gives way to occasional childishness. She''s a leader who sometimes needs to be taken care of by her followers.', 'https://zenless-zone-zero.fandom.com/wiki/Koleda%2FLore', 'Small & Cute, With Some Fierce Combat Power She may be small, but can certainly wield that huge hammer. A Fierce Young Girl Who''s Also a President The young leader at the helm of Belobog Industries. A President Who Leads by Example She prefers to work out in the field, rather than being stuck at a desk. Leads by Example While Maintaining Her Cute Nature Her maturity sometimes gives way to occasional childishness. She''s a leader who sometimes needs to be taken care of by her followers.', 'https://zenless-zone-zero.fandom.com/wiki/Koleda%2FLore', 'Pequeña y adorable, pero con una potencia de combate feroz: puede ser menuda, pero desde luego sabe manejar ese martillo enorme. Una joven fiera que además es presidenta: dirige Industrias Belobog desde la cúpula. Una presidenta que predica con el ejemplo: prefiere trabajar sobre el terreno antes que quedarse atrapada en un escritorio. Y una líder que conserva su lado tierno: su madurez deja paso de vez en cuando a la niña que lleva dentro, así que a veces son sus propios subordinados quienes tienen que cuidar de ella.', 'https://zenless-zone-zero.fandom.com/wiki/Koleda%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-lighter', 'zenless-zone-zero', 'Lighter', 'https://enka.network/ui/zzz/IconRoleCircle26.png', 'S', 'Fuego', 60, null, 'Sub-DPS / Debuffer', 'Aturdimiento', 'Corona de laureles', false, 'The "Red Scarf" and Champion of the Sons of Calydon, Lighter is an incredibly skilled fighter having experience from his time as a mercenary and underground fighter. Armed with an engine powered gauntlet, his duty is to fight the Champions of other biker gangs, a task he excels in, given he calls himself "the undefeated Champion."

According to Lighter himself, he is , fainting from just the sight of blood. To counter this, he always wears a pair of sunglasses, which also help him manage an old eye injury from his fighting days.', 'https://zenless-zone-zero.fandom.com/wiki/Lighter%2FLore', 'The "Red Scarf" and Champion of the Sons of Calydon, Lighter is an incredibly skilled fighter having experience from his time as a mercenary and underground fighter. Armed with an engine powered gauntlet, his duty is to fight the Champions of other biker gangs, a task he excels in, given he calls himself "the undefeated Champion."

According to Lighter himself, he is , fainting from just the sight of blood. To counter this, he always wears a pair of sunglasses, which also help him manage an old eye injury from his fighting days.', 'https://zenless-zone-zero.fandom.com/wiki/Lighter%2FLore', '"Pañuelo Rojo" y campeón de los Hijos de Calydon, Lighter es un luchador extraordinariamente hábil, curtido en su etapa de mercenario y de peleas clandestinas. Armado con un guantelete propulsado por un motor, su cometido es enfrentarse a los campeones de otras bandas de moteros, una tarea en la que destaca, no en vano se llama a sí mismo "el campeón invicto".

Según él mismo cuenta, se desmaya solo con ver sangre. Para evitarlo lleva siempre unas gafas de sol, que además le ayudan con una vieja lesión ocular de sus años de combate.', 'https://zenless-zone-zero.fandom.com/wiki/Lighter%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-lucia', 'zenless-zone-zero', 'Lucía', 'https://enka.network/ui/zzz/IconRoleCircle50.png', 'S', 'Éter', null, null, 'Apoyo', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport01.webp","nombre":"Insignia auxiliar básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":20}]}]'::jsonb),
  ('zzz-lucy', 'zenless-zone-zero', 'Lucy', 'https://enka.network/ui/zzz/IconRoleCircle27.png', 'A', 'Fuego', 60, null, 'Buffer', 'Apoyo', 'Cañón catapum', false, 'Luciana de Montefio, whose full name is Luciana Auxesis Theodoro de Montefio, is the daughter of the current head of the prestigious New Eridu Montefio family. Her personality is usually akin to that of a , seemingly acting harsh when she actually is compassionate and kind underneath, which may have been caused by her severed family ties and Outer Ring life.

Referring to herself as solely Lucy, due to her real name being far too long and not wanting to be involved with her family, she now performs the role of "Boar Thiren Overseer" for the "Leaps and Bounds Express Services Co.," a name used by the Sons of Calydon for their official logistics business.

Due to Lucy being considered a missing person, with there being a sizable reward for her safe return to her family, she prefers to stay in the Outer Ring, seldomly returning to the city.', 'https://zenless-zone-zero.fandom.com/wiki/Lucy%2FLore', 'Luciana de Montefio, whose full name is Luciana Auxesis Theodoro de Montefio, is the daughter of the current head of the prestigious New Eridu Montefio family. Her personality is usually akin to that of a , seemingly acting harsh when she actually is compassionate and kind underneath, which may have been caused by her severed family ties and Outer Ring life.

Referring to herself as solely Lucy, due to her real name being far too long and not wanting to be involved with her family, she now performs the role of "Boar Thiren Overseer" for the "Leaps and Bounds Express Services Co.," a name used by the Sons of Calydon for their official logistics business.

Due to Lucy being considered a missing person, with there being a sizable reward for her safe return to her family, she prefers to stay in the Outer Ring, seldomly returning to the city.', 'https://zenless-zone-zero.fandom.com/wiki/Lucy%2FLore', 'Luciana de Montefio, de nombre completo Luciana Auxesis Theodoro de Montefio, es la hija del actual cabeza de la prestigiosa familia Montefio de Nueva Eridu. Suele mostrarse dura por fuera cuando en realidad es compasiva y bondadosa, algo que quizá tenga que ver con la ruptura con su familia y con su vida en el Anillo Exterior.

Se hace llamar simplemente Lucy, porque su nombre real es demasiado largo y no quiere saber nada de los suyos. Ahora ejerce de "supervisora de los tirenes jabalí" en la empresa de logística Leaps and Bounds Express, el nombre con el que los Hijos de Calydon gestionan su negocio oficial de transporte.

Como figura en la lista de personas desaparecidas y hay una jugosa recompensa por devolverla sana y salva a su familia, prefiere quedarse en el Anillo Exterior y rara vez vuelve a la ciudad.', 'https://zenless-zone-zero.fandom.com/wiki/Lucy%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport01.webp","nombre":"Insignia auxiliar básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":20}]}]'::jsonb),
  ('zzz-lycaon', 'zenless-zone-zero', 'Lycaon (Von Lycaon)', 'https://enka.network/ui/zzz/IconRoleCircle18.png', 'S', 'Hielo', 60, null, 'Sub-DPS / Debuffer', 'Aturdimiento', 'Restricción inquebrantable', false, 'Can resolve any matter. The most trusted of attendants, and solid support for any team. Rational and wise, a true gentleman who can''t tolerate a single stain. Offers absolute loyalty to the one he decides to follow. Though outwardly sophisticated and rational, his innate feral character will reveal itself when faced with certain dangers.', 'https://zenless-zone-zero.fandom.com/wiki/Lycaon%2FLore', 'Can resolve any matter. The most trusted of attendants, and solid support for any team. Rational and wise, a true gentleman who can''t tolerate a single stain. Offers absolute loyalty to the one he decides to follow. Though outwardly sophisticated and rational, his innate feral character will reveal itself when faced with certain dangers.', 'https://zenless-zone-zero.fandom.com/wiki/Lycaon%2FLore', 'Capaz de resolver cualquier asunto. El más fiable de los mayordomos y un apoyo sólido para cualquier equipo. Racional y sensato, todo un caballero incapaz de tolerar una sola mancha. Ofrece lealtad absoluta a aquel a quien decide servir. Aunque por fuera resulte sofisticado y racional, su carácter salvaje innato aflora cuando se enfrenta a ciertos peligros.', 'https://zenless-zone-zero.fandom.com/wiki/Lycaon%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-manato', 'zenless-zone-zero', 'Manato', 'https://enka.network/ui/zzz/IconRoleCircle51.png', 'A', 'Fuego', null, null, 'Ruptura', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin01.webp","nombre":"Insignia disruptiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin02.webp","nombre":"Insignia disruptiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin02.webp","nombre":"Insignia disruptiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin03.webp","nombre":"Insignia dictaminadora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankRuin03.webp","nombre":"Insignia dictaminadora","cantidad":20}]}]'::jsonb),
  ('zzz-miyabi', 'zenless-zone-zero', 'Miyabi', 'https://enka.network/ui/zzz/IconRoleCircle13.png', 'S', 'Hielo', 60, null, 'DPS (DoT)', 'Anomalía', 'Motor-W de firma de Miyabi', false, 'The youngest Void Hunter to date and Chief of Hollow Special Operations Section 6, Hoshimi Miyabi is a woman who defies the status quo and uses Tailless, her family heirloom''s cursed blade, to protect the city of New Eridu and unveil the corruption within it. However, despite being the chief, Miyabi does little work related to it, with bureaucratic tasks being handled by Deputy Chief Tsukishiro Yanagi.

Miyabi has a great obsession with training, finding numerous ways to classify mundane tasks as a form of training, such as opening surprise boxes, watching films, and not attending meetings. The intensity of some of her training leads her to black out and enter a trance-like state, where''s she''s only capable of parroting the last word said by another.', 'https://zenless-zone-zero.fandom.com/wiki/Miyabi%2FLore', 'The youngest Void Hunter to date and Chief of Hollow Special Operations Section 6, Hoshimi Miyabi is a woman who defies the status quo and uses Tailless, her family heirloom''s cursed blade, to protect the city of New Eridu and unveil the corruption within it. However, despite being the chief, Miyabi does little work related to it, with bureaucratic tasks being handled by Deputy Chief Tsukishiro Yanagi.

Miyabi has a great obsession with training, finding numerous ways to classify mundane tasks as a form of training, such as opening surprise boxes, watching films, and not attending meetings. The intensity of some of her training leads her to black out and enter a trance-like state, where''s she''s only capable of parroting the last word said by another.', 'https://zenless-zone-zero.fandom.com/wiki/Miyabi%2FLore', 'La cazadora del Vacío más joven de la historia y jefa de la Sección 6 de Operaciones Especiales de Hollows, Hoshimi Miyabi es una mujer que desafía lo establecido y que usa Descolada, la hoja maldita heredada de su familia, para proteger Nueva Eridu y destapar la corrupción que la carcome. Sin embargo, pese a ser la jefa, apenas se ocupa de las tareas del cargo: de la burocracia se encarga la subjefa Tsukishiro Yanagi.

Miyabi está obsesionada con entrenar y encuentra mil maneras de clasificar actividades cotidianas como entrenamiento: abrir cajas sorpresa, ver películas o no asistir a reuniones. La intensidad de algunas de esas sesiones la lleva a desmayarse y entrar en una especie de trance en el que solo es capaz de repetir la última palabra que ha dicho otra persona.', 'https://zenless-zone-zero.fandom.com/wiki/Miyabi%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
