  ('zzz-nangong-yu', 'zenless-zone-zero', 'Nangong Yu', 'https://enka.network/ui/zzz/IconRoleCircle59.png', 'S', 'Éter', null, null, 'Aturdimiento', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-nekomata', 'zenless-zone-zero', 'Nekomata', 'https://enka.network/ui/zzz/IconRoleCircle11.png', 'S', 'Físico', 60, null, 'DPS', 'Ataque', 'Cuna de acero', false, '"The best mackerel is always the one you haven''t eaten yet~" — Nekomiya Mana Spirited and mischievous, she likes to play tricks on others. Your wallet is her wallet. (Really... It''s hers now.) Athletic and daring, no Hollow is too dangerous for her. "Cats love fish" is actually an incorrect stereotype. But Nekomata does love fish... She''s seen a lot of cat-astrophy and "curiosity killed the cat" moments, and seen many a secret that can''t be told.', 'https://zenless-zone-zero.fandom.com/wiki/Nekomata%2FLore', '"The best mackerel is always the one you haven''t eaten yet~" — Nekomiya Mana Spirited and mischievous, she likes to play tricks on others. Your wallet is her wallet. (Really... It''s hers now.) Athletic and daring, no Hollow is too dangerous for her. "Cats love fish" is actually an incorrect stereotype. But Nekomata does love fish... She''s seen a lot of cat-astrophy and "curiosity killed the cat" moments, and seen many a secret that can''t be told.', 'https://zenless-zone-zero.fandom.com/wiki/Nekomata%2FLore', '"El mejor jurel siempre es el que aún no te has comido~" — Nekomiya Mana. Vivaracha y traviesa, le encanta gastar bromas a los demás. Tu cartera es su cartera (en serio... ya es suya). Atlética y atrevida, no hay Hollow demasiado peligroso para ella. Lo de que "a los gatos les encanta el pescado" es en realidad un tópico falso, pero a Nekomata sí que le encanta el pescado... Ha vivido un montón de situaciones de las que dejan pelos de punta y ha visto muchos secretos que no se pueden contar.', 'https://zenless-zone-zero.fandom.com/wiki/Nekomata%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-nicole', 'zenless-zone-zero', 'Nicole Demara', 'https://enka.network/ui/zzz/IconRoleCircle12.png', 'A', 'Etéreo', 60, null, 'Debuffer (Defensa)', 'Apoyo', 'La caja fuerte', false, 'The leader of the odd-job agency the Cunning Hares, who accept all kinds of Hollow-related commissions. She''s been on the streets for many years, and has a reputation among her peers as being exceedingly cunning. She''s been blacklisted by many clients due to her all-or nothing approach. She loves money, but is surprisingly bad at managing it, leaving the Cunning Hares constantly on the edge of bankruptcy and owing many debts.

Nicole Demara is the founder and current leader of the Cunning Hares odd-job agency. Despite taking on any and all Hollow-related commissions and typically charging a high commission fee, she struggles with finances, leading the Cunning Hares to frequently be in debt, sometimes bordering on bankruptcy.', 'https://zenless-zone-zero.fandom.com/wiki/Nicole%2FLore', 'The leader of the odd-job agency the Cunning Hares, who accept all kinds of Hollow-related commissions. She''s been on the streets for many years, and has a reputation among her peers as being exceedingly cunning. She''s been blacklisted by many clients due to her all-or nothing approach. She loves money, but is surprisingly bad at managing it, leaving the Cunning Hares constantly on the edge of bankruptcy and owing many debts.

Nicole Demara is the founder and current leader of the Cunning Hares odd-job agency. Despite taking on any and all Hollow-related commissions and typically charging a high commission fee, she struggles with finances, leading the Cunning Hares to frequently be in debt, sometimes bordering on bankruptcy.', 'https://zenless-zone-zero.fandom.com/wiki/Nicole%2FLore', 'La líder de la agencia de encargos Liebres Astutas, que acepta todo tipo de trabajos relacionados con los Hollows. Lleva muchos años en la calle y entre sus colegas tiene fama de ser extremadamente astuta. Muchos clientes la han puesto en su lista negra por su forma de jugárselo todo a una carta. Adora el dinero, pero se le da sorprendentemente mal administrarlo, lo que mantiene a las Liebres Astutas al borde de la quiebra y llenas de deudas.

Nicole Demara es la fundadora y actual líder de la agencia de encargos Liebres Astutas. Pese a aceptar cualquier trabajo relacionado con los Hollows y cobrar comisiones altas, tiene problemas con las cuentas, así que el grupo vive endeudado y a veces rozando la bancarrota.', 'https://zenless-zone-zero.fandom.com/wiki/Nicole%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport01.webp","nombre":"Insignia auxiliar básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":20}]}]'::jsonb),
