  ('zzz-pan-yinhu', 'zenless-zone-zero', 'Pan Yinhu', 'https://enka.network/ui/zzz/IconRoleCircle45.png', 'A', 'Físico', null, null, 'Defensa', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield01.webp","nombre":"Insignia defensiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":20}]}]'::jsonb),
  ('zzz-piper', 'zenless-zone-zero', 'Piper Wheel', 'https://enka.network/ui/zzz/IconRoleCircle28.png', 'A', 'Físico', 60, null, 'Sub-DPS / Debuffer', 'Anomalía', 'Viaje rugiente', false, 'We''re behind schedule! Today''s the day that we need to share the new archive with the Proxies! A petrolhead and a driver who often leaves her passengers feeling scared, that can only be Pi— Piper: "Buckled up? Then let''s go!"

"Ya need a lift? Then buckle up, buddy." Piper Wheel "If you get carsick, look out the window at the view, and you''ll feel better." "Next, it''s time for lil ol'' me to clock in and get to work." "Buckle~ Up~!"', 'https://zenless-zone-zero.fandom.com/wiki/Piper%2FLore', 'We''re behind schedule! Today''s the day that we need to share the new archive with the Proxies! A petrolhead and a driver who often leaves her passengers feeling scared, that can only be Pi— Piper: "Buckled up? Then let''s go!"

"Ya need a lift? Then buckle up, buddy." Piper Wheel "If you get carsick, look out the window at the view, and you''ll feel better." "Next, it''s time for lil ol'' me to clock in and get to work." "Buckle~ Up~!"', 'https://zenless-zone-zero.fandom.com/wiki/Piper%2FLore', '¡Vamos con retraso! ¡Hoy es el día en que hay que compartir el nuevo archivo con los Proxies! Amante de los motores y conductora capaz de dejar a sus pasajeros muertos de miedo, solo puede ser Pi... Piper: "¿Cinturón puesto? ¡Pues allá vamos!".

"¿Necesitas que te lleve? Pues abróchate el cinturón, colega". Piper Wheel. "Si te mareas, mira el paisaje por la ventanilla y se te pasará". "Y ahora le toca a una servidora fichar y ponerse a trabajar". "¡Cinturón~ puesto~!".', 'https://zenless-zone-zero.fandom.com/wiki/Piper%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
