  ('zzz-pyrois', 'zenless-zone-zero', 'Pyrois', 'https://enka.network/ui/zzz/IconRoleCircle63.png', 'S', 'Éter', null, null, 'Ataque', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-qingyi', 'zenless-zone-zero', 'Qingyi', 'https://enka.network/ui/zzz/IconRoleCircle29.png', 'S', 'Eléctrico', 60, null, 'Sub-DPS / Debuffer', 'Aturdimiento', 'Tetera de jade helado', false, 'Qingyi, or 01 Neo-Genesis VI, is an experienced Public Security officer and novice investigator. With a personally modified riot baton, she fights crime in New Eridu. The most notable thing about Qingyi is her mature personality, having built it off of Old Civilization media and her own very long life. She spends her free time with the elderly citizens of New Eridu, playing chess and drinking hot water. Compared to other Public Security officers, Qingyi is incredibly laid-back, from playing pranks on her other members to working with Proxies.', 'https://zenless-zone-zero.fandom.com/wiki/Qingyi%2FLore', 'Qingyi, or 01 Neo-Genesis VI, is an experienced Public Security officer and novice investigator. With a personally modified riot baton, she fights crime in New Eridu. The most notable thing about Qingyi is her mature personality, having built it off of Old Civilization media and her own very long life. She spends her free time with the elderly citizens of New Eridu, playing chess and drinking hot water. Compared to other Public Security officers, Qingyi is incredibly laid-back, from playing pranks on her other members to working with Proxies.', 'https://zenless-zone-zero.fandom.com/wiki/Qingyi%2FLore', 'Qingyi, o 01 Neogénesis VI, es una veterana oficial de Seguridad Pública y una investigadora novata. Con una porra antidisturbios modificada por ella misma, combate el crimen en Nueva Eridu. Lo más llamativo de Qingyi es su personalidad madura, forjada a partir de los medios de la Vieja Civilización y de su propia y larguísima vida. Dedica su tiempo libre a los ancianos de Nueva Eridu, jugando al ajedrez y bebiendo agua caliente. Comparada con el resto de agentes de Seguridad Pública, Qingyi es tremendamente relajada: lo mismo gasta bromas a sus compañeros que colabora con los Proxies.', 'https://zenless-zone-zero.fandom.com/wiki/Qingyi%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-remielle', 'zenless-zone-zero', 'Remielle', 'https://enka.network/ui/zzz/IconRoleCircle67.png', 'S', 'Lumen', null, null, 'Anomalía', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
  ('zzz-rina', 'zenless-zone-zero', 'Rina (Alexandrina)', 'https://enka.network/ui/zzz/IconRoleCircle22.png', 'S', 'Eléctrico', 60, null, 'Buffer (Perforación)', 'Apoyo', 'Cuna del llanto', false, 'Are you the new master? Rina from Victoria Housekeeping, at your service." "Oh my, would you look at the time? I just prepared some snacks~" "Allow me to bring them over for everyone~" "Ah! No, no thanks!!!" "W—We still have another interview next... We''ll be going now!"', 'https://zenless-zone-zero.fandom.com/wiki/Rina%2FLore', 'Are you the new master? Rina from Victoria Housekeeping, at your service." "Oh my, would you look at the time? I just prepared some snacks~" "Allow me to bring them over for everyone~" "Ah! No, no thanks!!!" "W—We still have another interview next... We''ll be going now!"', 'https://zenless-zone-zero.fandom.com/wiki/Rina%2FLore', '"¿Es usted el nuevo señor? Rina, de Victoria Housekeeping, a su servicio". "Vaya, ¿ya es esa hora? Acabo de preparar algo de picar~". "Permítanme traerlo para todos~". "¡Ah! ¡No, no, gracias!". "Aún... aún tenemos otra entrevista después... ¡Nos vamos ya!".', 'https://zenless-zone-zero.fandom.com/wiki/Rina%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport01.webp","nombre":"Insignia auxiliar básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":20}]}]'::jsonb),
  ('zzz-roxy', 'zenless-zone-zero', 'Roxy', 'https://enka.network/ui/zzz/IconRoleCircle68.png', 'S', 'Viento', null, null, 'Aturdimiento', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun01.webp","nombre":"Insignia aturdidora básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun02.webp","nombre":"Insignia aturdidora avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankStun03.webp","nombre":"Insignia rompefilas","cantidad":20}]}]'::jsonb),
  ('zzz-seth', 'zenless-zone-zero', 'Seth Lowell', 'https://enka.network/ui/zzz/IconRoleCircle30.png', 'A', 'Eléctrico', 60, null, 'Tanque / Buffer', 'Defensa', 'Pacificador', false, 'Seth is a member of the Criminal Investigation Special Response Team. According to the archive, Seth is currently learning the ropes in Zhu Yuan''s team. He is full of passion, is hardworking, and looks forward to the day that he''ll be able to hold his own in his job~

""Captain, I''ll apprehend the perp!" Seth Lowell "First, gotta pretend to be completely harmless..." "Ah... saw right through me, huh?" "Well, whatever, guess it''s time we talk with our fists instead!"', 'https://zenless-zone-zero.fandom.com/wiki/Seth%2FLore', 'Seth is a member of the Criminal Investigation Special Response Team. According to the archive, Seth is currently learning the ropes in Zhu Yuan''s team. He is full of passion, is hardworking, and looks forward to the day that he''ll be able to hold his own in his job~

""Captain, I''ll apprehend the perp!" Seth Lowell "First, gotta pretend to be completely harmless..." "Ah... saw right through me, huh?" "Well, whatever, guess it''s time we talk with our fists instead!"', 'https://zenless-zone-zero.fandom.com/wiki/Seth%2FLore', 'Seth es miembro del Equipo Especial de Respuesta de Investigación Criminal. Según el archivo, ahora mismo está aprendiendo el oficio en el equipo de Zhu Yuan. Le sobra entusiasmo, es muy trabajador y espera con ganas el día en que pueda valerse por sí mismo en el trabajo~

"¡Capitana, yo detendré al sospechoso!". Seth Lowell. "Primero hay que hacerse el inofensivo...". "Ah... me has calado, ¿eh?". "Bueno, da igual, ¡supongo que toca hablar a puñetazos!".', 'https://zenless-zone-zero.fandom.com/wiki/Seth%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield01.webp","nombre":"Insignia defensiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":20}]}]'::jsonb),
  ('zzz-sigrid', 'zenless-zone-zero', 'Sigrid', 'https://enka.network/ui/zzz/IconRoleCircle66.png', 'S', 'Hielo', null, null, 'Ataque', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-soldado-11', 'zenless-zone-zero', 'Soldado 11', 'https://enka.network/ui/zzz/IconRoleCircle05.png', 'S', 'Fuego', 60, null, 'DPS', 'Ataque', 'Azufre', false, 'A model soldier who follows orders and stays loyal to the mission... At least that''s what Soldier 11 demands of herself. Weapons don''t need emotions, and need only follow orders... At least that''s what Soldier 11 tells herself. No matter how strong the enemy, just get fired up and face it head on... At least that''s what Soldier 11 does. She''s shed her weakness along with her name, leaving only resolve... At least that''s what Soldier 11 thinks.

A soldier with no name and an affinity for fire. Soldier 11 is a model soldier of the New Eridu Defense Force, serving as the primary responder and first striker for Obol Squad.

Though an exceptional by-the-books soldier, Soldier 11 has notable quirks, namely her love for spicy food (specifically super-spicy noodles from Sixth Street''s Waterfall Soup)
and a habit of calling Phaethon by a different codename on every occasion.', 'https://zenless-zone-zero.fandom.com/wiki/Soldier%2011%2FLore', 'A model soldier who follows orders and stays loyal to the mission... At least that''s what Soldier 11 demands of herself. Weapons don''t need emotions, and need only follow orders... At least that''s what Soldier 11 tells herself. No matter how strong the enemy, just get fired up and face it head on... At least that''s what Soldier 11 does. She''s shed her weakness along with her name, leaving only resolve... At least that''s what Soldier 11 thinks.

A soldier with no name and an affinity for fire. Soldier 11 is a model soldier of the New Eridu Defense Force, serving as the primary responder and first striker for Obol Squad.

Though an exceptional by-the-books soldier, Soldier 11 has notable quirks, namely her love for spicy food (specifically super-spicy noodles from Sixth Street''s Waterfall Soup)
and a habit of calling Phaethon by a different codename on every occasion.', 'https://zenless-zone-zero.fandom.com/wiki/Soldier%2011%2FLore', 'Una soldado modélica que cumple órdenes y se mantiene fiel a la misión... o al menos eso es lo que Soldado 11 se exige a sí misma. Las armas no necesitan emociones, solo obedecer... o al menos eso es lo que Soldado 11 se repite. Por fuerte que sea el enemigo, basta con encenderse y plantarle cara... o al menos eso es lo que Soldado 11 hace. Se ha desprendido de su debilidad junto con su nombre y solo le queda la determinación... o al menos eso es lo que Soldado 11 cree.

Una soldado sin nombre y con afinidad por el fuego. Soldado 11 es una militar ejemplar de la Fuerza de Defensa de Nueva Eridu y actúa como primera respondiente y punta de lanza del Escuadrón Óbolo.

Pese a ser una soldado excepcional y de manual, tiene manías llamativas: le apasiona la comida picante (en concreto los fideos superpicantes del Waterfall Soup de la Sexta Calle) y llama a Phaethon por un nombre en clave distinto cada vez.', 'https://zenless-zone-zero.fandom.com/wiki/Soldier%2011%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb),
  ('zzz-soukaku', 'zenless-zone-zero', 'Soukaku', 'https://enka.network/ui/zzz/IconRoleCircle17.png', 'A', 'Hielo', 60, null, 'Buffer', 'Apoyo', 'Demonio tímido', false, 'Soukaku is the gluttonous, childlike Oni of Hollow Special Operations Section 6. She''s a powerful combatant who uses a custom made weapon known as an "Oni Blade Banner" in battle. Outside of battle, Soukaku has a notable interest in food, caring little about what she eats and hating when food is wasted. 

Even though Soukaku is stated to be older than her legal guardian, Tsukishiro Yanagi, Soukaku is still considered young for her species, requiring homeschooling and dependency on others.', 'https://zenless-zone-zero.fandom.com/wiki/Soukaku%2FLore', 'Soukaku is the gluttonous, childlike Oni of Hollow Special Operations Section 6. She''s a powerful combatant who uses a custom made weapon known as an "Oni Blade Banner" in battle. Outside of battle, Soukaku has a notable interest in food, caring little about what she eats and hating when food is wasted. 

Even though Soukaku is stated to be older than her legal guardian, Tsukishiro Yanagi, Soukaku is still considered young for her species, requiring homeschooling and dependency on others.', 'https://zenless-zone-zero.fandom.com/wiki/Soukaku%2FLore', 'Soukaku es la oni glotona e infantil de la Sección 6 de Operaciones Especiales de Hollows. Es una combatiente poderosa que usa en batalla un arma hecha a medida conocida como "estandarte de hoja oni". Fuera del combate, su gran interés es la comida: le da bastante igual lo que come y detesta que se desperdicie.

Aunque se dice que Soukaku es mayor que su tutora legal, Tsukishiro Yanagi, sigue considerándose joven para su especie, por lo que estudia en casa y depende de los demás.', 'https://zenless-zone-zero.fandom.com/wiki/Soukaku%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport01.webp","nombre":"Insignia auxiliar básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":20}]}]'::jsonb),
