  ('zzz-vivian', 'zenless-zone-zero', 'Vivian', 'https://enka.network/ui/zzz/IconRoleCircle41.png', 'S', 'Éter', null, null, 'Anomalía', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
  ('zzz-yanagi', 'zenless-zone-zero', 'Yanagi', 'https://enka.network/ui/zzz/IconRoleCircle31.png', 'S', 'Eléctrico', 60, null, 'DPS (DoT)', 'Anomalía', 'Tejetiempos', false, 'The Deputy Chief of Hollow Special Operations Section 6, Tsukishiro Yanagi is an ex-soldier and former administrative officer from the New Eridu Defense Force who has been infused with Oni blood. Her main jobs include general management, on-site support and being the guardian of her fellow member Soukaku; alongside all these duties, she usually finds herself having to complete the rest of the team''s tasks as well. Due to the unique personalities of the other Section 6 members, Yanagi''s seriousness and diligence classify her as the only "normal" member of the team. It is with her guidance, experience, and leadership that the primary on-field group''s powers combine into true combat power.', 'https://zenless-zone-zero.fandom.com/wiki/Yanagi%2FLore', 'The Deputy Chief of Hollow Special Operations Section 6, Tsukishiro Yanagi is an ex-soldier and former administrative officer from the New Eridu Defense Force who has been infused with Oni blood. Her main jobs include general management, on-site support and being the guardian of her fellow member Soukaku; alongside all these duties, she usually finds herself having to complete the rest of the team''s tasks as well. Due to the unique personalities of the other Section 6 members, Yanagi''s seriousness and diligence classify her as the only "normal" member of the team. It is with her guidance, experience, and leadership that the primary on-field group''s powers combine into true combat power.', 'https://zenless-zone-zero.fandom.com/wiki/Yanagi%2FLore', 'Subjefa de la Sección 6 de Operaciones Especiales de Hollows, Tsukishiro Yanagi es una exsoldado y antigua oficial administrativa de la Fuerza de Defensa de Nueva Eridu a la que se le ha infundido sangre oni. Sus funciones principales son la gestión general, el apoyo sobre el terreno y la tutela de su compañera Soukaku; además de todo eso, suele acabar completando también las tareas del resto del equipo. Dadas las peculiares personalidades de los demás miembros de la Sección 6, su seriedad y su diligencia la convierten en la única integrante "normal" del grupo. Es su guía, su experiencia y su liderazgo lo que hace que las capacidades del equipo de campo se combinen en auténtica potencia de combate.', 'https://zenless-zone-zero.fandom.com/wiki/Yanagi%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff01.webp","nombre":"Insignia anómala básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff02.webp","nombre":"Insignia anómala avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankBuff03.webp","nombre":"Insignia controladora","cantidad":20}]}]'::jsonb),
