  ('zzz-yuzuha', 'zenless-zone-zero', 'Yuzuha', 'https://enka.network/ui/zzz/IconRoleCircle47.png', 'S', 'Físico', null, null, 'Apoyo', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport01.webp","nombre":"Insignia auxiliar básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport02.webp","nombre":"Insignia auxiliar avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankSupport03.webp","nombre":"Insignia dominante","cantidad":20}]}]'::jsonb),
  ('zzz-zhao', 'zenless-zone-zero', 'Zhao', 'https://enka.network/ui/zzz/IconRoleCircle56.png', 'S', 'Hielo', null, null, 'Defensa', null, null, false, null, null, null, null, null, null, false, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield01.webp","nombre":"Insignia defensiva básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield02.webp","nombre":"Insignia defensiva avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankShield03.webp","nombre":"Insignia protectora","cantidad":20}]}]'::jsonb),
  ('zzz-zhu-yuan', 'zenless-zone-zero', 'Zhu Yuan', 'https://enka.network/ui/zzz/IconRoleCircle23.png', 'S', 'Etéreo', 60, null, 'DPS', 'Ataque', 'Pacificador antidisturbios VI', false, 'Officer 148; Zhu Yuan, is an exceptional PubSec officer and current captain of the Criminal Investigation Special Response Team. A skilled martial artist and sharpshooter, Zhu Yuan uses the custom-made and versatile ''Suppressor K22'' firearm in conjunction with swift punches and kicks to take down criminals. As a reputable officer, Zhu Yuan has a strict moral compass, looking down on criminals, but is shown to be okay with taking the assistance of Proxies if the situation calls for it.

Zhu Yuan is a notable perfectionist, having set herself high standards to the point she has a complex, though such perfectionism has granted her exceptional experience and a record of no unresolved cases. She also exhibits an obsession with neatness, namely when it comes to her uniform. She''s shown to be cautious around cats and other small furry animals due to the fur they shed.

Zhu Yuan is shown to have a good relationship with her parents.', 'https://zenless-zone-zero.fandom.com/wiki/Zhu%20Yuan%2FLore', 'Officer 148; Zhu Yuan, is an exceptional PubSec officer and current captain of the Criminal Investigation Special Response Team. A skilled martial artist and sharpshooter, Zhu Yuan uses the custom-made and versatile ''Suppressor K22'' firearm in conjunction with swift punches and kicks to take down criminals. As a reputable officer, Zhu Yuan has a strict moral compass, looking down on criminals, but is shown to be okay with taking the assistance of Proxies if the situation calls for it.

Zhu Yuan is a notable perfectionist, having set herself high standards to the point she has a complex, though such perfectionism has granted her exceptional experience and a record of no unresolved cases. She also exhibits an obsession with neatness, namely when it comes to her uniform. She''s shown to be cautious around cats and other small furry animals due to the fur they shed.

Zhu Yuan is shown to have a good relationship with her parents.', 'https://zenless-zone-zero.fandom.com/wiki/Zhu%20Yuan%2FLore', 'La agente 148, Zhu Yuan, es una oficial excepcional de Seguridad Pública y actual capitana del Equipo Especial de Respuesta de Investigación Criminal. Experta en artes marciales y tiradora de élite, combina el arma personalizada y versátil "Supresor K22" con puñetazos y patadas rápidas para detener a los criminales. Como agente respetada, tiene una brújula moral estricta y mira por encima del hombro a los delincuentes, aunque acepta la ayuda de los Proxies cuando la situación lo requiere.

Zhu Yuan es una perfeccionista de manual: se ha impuesto un listón tan alto que le ha creado un complejo, si bien esa misma exigencia le ha dado una experiencia excepcional y un historial sin un solo caso sin resolver. También es obsesiva con la pulcritud, sobre todo con su uniforme, y desconfía de los gatos y demás animales peludos por el pelo que sueltan.', 'https://zenless-zone-zero.fandom.com/wiki/Zhu%20Yuan%2FLore', true, '[{"desde":10,"hasta":20,"creditos":24000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage01.webp","nombre":"Insignia atacante básica","cantidad":4}]},{"desde":20,"hasta":30,"creditos":56000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":12}]},{"desde":30,"hasta":40,"creditos":120000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage02.webp","nombre":"Insignia atacante avanzada","cantidad":20}]},{"desde":40,"hasta":50,"creditos":200000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":10}]},{"desde":50,"hasta":60,"creditos":400000,"materiales":[{"icono":"https://static.nanoka.cc/assets/zzz/AvatarRankDamage03.webp","nombre":"Insignia del pionero","cantidad":20}]}]'::jsonb)
