      name = excluded.name,
      image_url = excluded.image_url,
      rarity = excluded.rarity,
      element = excluded.element,
      level_cap = excluded.level_cap,
      description = excluded.description,
      role = excluded.role,
      path = excluded.path,
      signature = excluded.signature,
      is_upcoming = excluded.is_upcoming,
      biography = excluded.biography,
      biography_source = excluded.biography_source,
      biography_en = excluded.biography_en,
      biography_source_en = excluded.biography_source_en,
      biography_es = excluded.biography_es,
      biography_source_es = excluded.biography_source_es,
      biography_es_translated = excluded.biography_es_translated,
      ascension = excluded.ascension;

